// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }
    function testFuzz_property(address from, address to, uint256 v) public {
        vm.assume(to != address(0) && from != address(0) && v > 0);
        address[] memory tos = new address[](1);
        tos[0] = to;
        StrictCallee callee = new StrictCallee();
        bool ok;
        try c.transfer(from, address(callee), tos, v) returns (bool ret) {
            ok = ret;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

contract StrictCallee {
    fallback(bytes calldata input) external payable returns (bytes memory) {
        bytes4 sel = bytes4(input[:4]);
        require(sel == bytes4(keccak256("transferFrom(address,address,uint256)")), "unexpected selector");
        return "";
    }
}
